def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or (r,c) in seen:
                continue
            q = deque([(r,c)])
            seen.add((r,c))
            comp = []
            touches_edge = False
            while q:
                y,x = q.popleft(); comp.append((y,x))
                if y == 0 or x == 0 or y == h-1 or x == w-1:
                    touches_edge = True
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny,nx=y+dy,x+dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 0 and (ny,nx) not in seen:
                        seen.add((ny,nx)); q.append((ny,nx))
            if touches_edge:
                continue
            boundary = set()
            for y,x in comp:
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny,nx=y+dy,x+dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 1:
                        boundary.add((ny,nx))
            if not boundary:
                continue
            inside = set(comp)
            for y,x in comp:
                if any(0 <= y+dy < h and 0 <= x+dx < w and grid[y+dy][x+dx] == 1
                       for dy in (-1,0,1) for dx in (-1,0,1) if dy or dx):
                    out[y][x] = 3
            for y,x in boundary:
                for dy in (-1,0,1):
                    for dx in (-1,0,1):
                        ny,nx=y+dy,x+dx
                        if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 0 and (ny,nx) not in inside:
                            out[ny][nx] = 2
    return out
'''
